import sys

def rank(perm, n, fact):
    unused = list(range(1, n + 1))
    r = 0
    for i, x in enumerate(perm):
        smaller = 0
        for y in unused:
            if y < x:
                smaller += 1
            else:
                break
        r += smaller * fact[n - i - 1]
        unused.remove(x)
    return r

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]
    q = data[1 + n:1 + 2 * n]

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    rank_p = rank(p, n, fact)
    rank_q = rank(q, n, fact)

    ans = rank_q - rank_p - 1
    if ans < 0:
        ans = 0

    print(ans)

