import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    mod = MOD

    # Modular inverses of 1..N
    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = mod - (mod // i) * inv[mod % i] % mod

    # Convert inv array in-place to prefix sums H[i] = 1 + 1/2 + ... + 1/i
    s = 0
    for i in range(1, N + 1):
        s += inv[i]
        if s >= mod:
            s -= mod
        inv[i] = s

    H = inv

    # w_i = sum of 1/length over all subarrays containing position i
    w = H[N]
    ans = 0

    for i in range(1, N + 1):
        ans = (ans + data[i] * w) % mod
        if i < N:
            w += H[N - i] - H[i]
            if w < 0:
                w += mod
            elif w >= mod:
                w -= mod

    print(ans)

if __name__ == "__main__":
    main()

