from bisect import bisect_left

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    n = next(it)

    current_max = 0
    records = 0
    tails = []

    for p in it:
        if p > current_max:
            # This element is a prefix maximum, so it must be counted.
            records += 1
            current_max = p
        else:
            # Counted non-record elements can form one increasing subsequence.
            i = bisect_left(tails, p)
            if i == len(tails):
                tails.append(p)
            else:
                tails[i] = p

    print(records + len(tails))

