        du = dist[u]
        smallest = min_out[u]

        for v in adj[u]:
            if visited[v]:
                continue

            if v == smallest:
                if du < dist[v]:
                    dist[v] = du
                    dq.appendleft(v)
            else:
                nd = du + 1
                if nd < dist[v]:
                    dist[v] = nd
                    dq.append(v)

    ans = dist[T]
    print(-1 if ans == INF else ans)

